fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut lo = 0;
    let mut hi = arr.len();

    // Invariant: the first occurrence, if it exists, must be in [lo, hi)
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < target {
            // target must be to the right of mid
            lo = mid + 1;
        } else {
            // arr[mid] >= target, so first occurrence is at or to the left of mid
            hi = mid;
        }
    }

    // lo is now the smallest index such that arr[lo] >= target (or lo == arr.len())
    if lo < arr.len() && arr[lo] == target {
        Some(lo)
    } else {
        None
    }
}

